event.res.headers.set("accept-ranges", "bytes");

// Range is only honoured when the asset size is known and `If-Range` (if any)
// still matches the current validators. Otherwise the full body is served.
const rangeHeader = event.req.headers.get("range");
const range =
  rangeHeader &&
  meta.size !== undefined &&
  matchesIfRange(event.req.headers.get("if-range"), meta.etag, mtimeDate)
    ? parseRange(rangeHeader, meta.size)
    : undefined;

// Decided before the representation headers so a 416 carries no content-type
// or content-encoding of a body that does not exist.
